    // MARK: - After the sweepstakes parlor

    static let parlorSecondRobbery = followUp(
        key: "story.followup.parlorSecondRobbery", category: .robbery,
        headlines: ["Convenience Store Clerk Robbed; Suspect Has Prior Parlor Case", "Second Robbery Charge for Man in Sweepstakes Case"],
        law: "commonLawRobbery", threshold: 6, spec: "Took $412 from the person and presence of {V}, a store clerk, by violence and putting {V.him} in fear, on {DATE}.", ages: 19...42, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} walked into a convenience store on {STREET} at 3 a.m. on {DATE}, reached across the counter, shoved the clerk, {V}, into the cigarette rack, and grabbed $412 from the open drawer. No weapon this time. The store's camera caught the face clearly, and {V} picked {DL} from a photo lineup the next day.",
        state: [E(.video, 3, "Store Camera", "A clear view of the robber's face as he leans across the counter and shoves {V}."),
                E(.document, 2, "Photo Lineup", "{V} picked {DL} from six photos, 90 percent sure, the morning after.")],
        defense: [E(.statement, 1, "Alibi", "{DL}'s girlfriend says {D.he} was asleep beside her at 3 a.m.")],
        witnessRole: "Police detective",
        exam: [.direct("What does the camera show?", "\"A clear face, leaning over the counter, a shove, the drawer.\""),
               .direct("How was the lineup run?", "\"Double-blind. The officer showing the photos didn't know which one was {DL}.\""),
               .direct("What happened at the convenience store?", "\"A man walked in at 3 a.m. on {STREET}, reached across the counter, shoved the clerk, {V}, into the cigarette rack, and took $412 from the open drawer.\""),
               .direct("Was a weapon used?", "\"No weapon this time. It was just a shove into a metal rack.\""),
               .direct("How did {V} identify the robber?", "\"{V} picked {DL} from six photos the next morning, 90 percent sure. The lineup was double-blind.\""),
               .direct("What did the clerk tell you at the scene?", "\"That a man leaned over the counter, shoved {V.him} into the cigarette rack, and took the cash from the drawer, all in under a minute.\""),
                    .cross("The girlfriend says {DL} was home.", "\"She also told us she was asleep.\""),
               .cross("No weapon this time.", "\"No. Just a shove into a metal rack.\""),
               .cross("The clerk said 90 percent sure?", "\"Yes. {V} was scared and picked the photo that looked like the man.\""),
               .cross("A cousin who looks like {DL} was arrested?", "\"A cousin who looks much like {DL} was arrested in the next county with the store's bank bag. {DL}'s phone also pinged the tower behind the store at 2:58 a.m.\""),
                    .cross("The lineup photo was shown the morning after, with the clerk still shaken?", "\"Yes, about eight hours after. The clerk had calmed down, and the officer reading the instructions did not know which photo was {DL}'s.\"")],
        theory: ("{D} shoved a clerk into a rack and took the drawer, and the camera got {D.his} face.", "A stranger on a camera and an alibi the State can't disprove."),
        allocution: "\"That night I was home in bed, and that picture only looks like me. I'm not going to lie this time. I need help with the gambling. I'm sorry to the clerk, and I'll go to treatment.\"",
        truths: ("{DL}'s phone pinged the tower behind the store at 2:58 a.m.",
                 "A cousin who looks much like {DL} was arrested in the next county with the store's bank bag."),
        defendant: [.direct("Where were you at 3 a.m.?", "\"Home in bed. I was asleep at 3 a.m., and my phone was on the charger.\""),
               .direct("Is that you on the video?", "\"It looks like me. It isn't.\""),
               .direct("Do you have a cousin who looks like you?", "\"I do. We have the same face, and people mix us up all the time. He has been in trouble before.\""),
               .direct("Why would your phone ping a tower near the store?", "\"I do not know. I live in that area, and my phone pings the nearest tower all night.\""),
               .direct("What do you do for work?", "\"I work nights at a warehouse, and I am home most nights by two. I was off that night and asleep by midnight.\""), .direct("Have you ever been to that store?", "\"I have bought gas near there. I have never been in that convenience store, and I do not know the clerk.\""),
                    .cross("After your last case, you were told to stay away from gambling places.", "\"This was a gas station.\""),
               .cross("The clerk picked you out of six photos.", "\"The clerk was scared and had only seconds to look. I think that is why {V.he} chose me out of the six, and I think {V.he} is mistaken.\""),
               .cross("Your girlfriend was asleep too.", "\"She was. She cannot say where I was at 3 a.m., and I understand that is a weakness in my alibi.\""),
                    .cross("Your phone connected to the tower behind the store at 2:58.", "\"I live a few blocks from there. My phone connects to that tower all night when it is on the charger.\""), .cross("The store camera shows a clear face.", "\"It looks like my face, and it is not me. My cousin has the same nose and the same jaw.\"")],
        openings: ("At 3 a.m. a man leaned across the counter of a convenience store, shoved the clerk, {V}, into a cigarette rack, and took $412 from the drawer. The camera caught the face clearly, and {V} picked {D} from six photos the next morning.", "The defense will say {D} was asleep at home at 3 a.m. and that a cousin who looks much like {D} was arrested in the next county with the store's bank bag."),
        closings: ("A clear face on camera, a double-blind lineup, and {D}'s phone pinging the tower behind the store at 2:58 a.m. {D} was back after {PRIOR}.", "A look-alike cousin was caught with the store's bank bag, and {D}'s girlfriend places {D.him} in bed. The State must prove it was {D} on the camera and not the cousin."),
        timeline: [(0, "3:02 a.m.: robbery."), (1, "Photo lineup; {V} picks {DL}.")],
        identified: "The store camera and a photo lineup.",
        impact: "\"My shoulder still pops when I lift the drink crates. I was restocking when a man reached across the counter and shoved me into the cigarette rack. I picked {D.him} from a photo lineup the next day. I work nights alone, and I keep a chair against the door now.\"",
        doctrines: ["eyewitnessID", "burdenOfProof"])

    // MARK: - After the tobacco barn

    static let barnNeighborThreat = followUp(
        key: "story.followup.barnNeighborThreat", category: .publicOrder,
        headlines: ["Farmer Charged With Threatening Neighbor Who Testified About Barn Fire", "Threat Charge Follows Barn Fire Case"],
        law: "communicatingThreats", threshold: 5, spec: "Willfully threatened to burn the home of {V}, a witness in an earlier case, in a manner a reasonable person would believe would be carried out, on {DATE}.", ages: 40...72, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} drove to the farm of {V}, a neighbor who had talked to the fire investigator, and said across the fence: \"You know how fast an old house goes up. Think about that tonight.\" {V}'s teenage son recorded the last part on his phone.",
        state: [E(.video, 3, "Phone Video", "{D} at the fence: \"Think about that tonight.\""),
                E(.statement, 2, "Son's Account", "The son heard the first part: \"You know how fast an old house goes up.\"")],
        defense: [E(.statement, 1, "Context", "{DL} says {D.he} was talking about {V}'s own wiring, which {D.he} had warned {V} about for years.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What did {V} do after?", "\"Sat up all night with a shotgun and the porch light on, then called us at dawn.\""),
               .direct("Had {DL} said anything about wiring before?", "\"Not that {V} ever mentioned.\""),
               .direct("What was {V}'s connection to the earlier case?", "\"{V} is a neighbor who had talked to the fire investigator about the barn fire. {DL} believed {V} was one of the people who pointed investigators his way.\""),
               .direct("What did {DL} say at the fence?", "\"'You know how fast an old house goes up. Think about that tonight.' {V}'s teenage son recorded the last part on his phone.\""),
               .direct("Who heard the first part?", "\"The son did. He was at the fence a few steps from his father and heard the sentence about how fast an old house goes up.\""),
               .direct("How did {V} react?", "\"{V} sat up all night with a shotgun and the porch light on. {V} called us at dawn and gave us the phone video.\""),
               .cross("The video only has the last sentence.", "\"The son heard the first one.\""),
               .cross("'Think about that' isn't a promise to do anything.", "\"After a barn fire case, it is.\""),
               .cross("{DL} warned {V} about wiring in the past?", "\"{DL}'s electrician says he told {V} about the wiring twice the year before. {V} never mentioned that to me.\""),
               .cross("{DL} did not threaten to burn anything in so many words?", "\"He did not use the word burn. He said how fast an old house goes up and told {V} to think about it tonight, after a barn fire case.\""),
                    .cross("{DL} could have been warning {V} about the wiring?", "\"If there had been no barn fire case, I might believe that. The words 'think about that tonight' came after it, and the son heard the first sentence about how fast an old house burns.\"")],
        theory: ("{D} told a witness against {D.him} how fast an old house burns, and to think about it tonight.", "A warning about bad wiring, overheard in pieces by a teenager."),
        allocution: "\"I drove out to say that {V}'s wiring would burn that house down someday. I wanted to tell {V.him} I knew what {V.he} had said about me. I was angry. I lost my temper at a man I thought turned on me, and I'm sorry.\"",
        truths: ("{DL} drove past {V}'s house three more times that night, a neighbor's camera showed.",
                 "{DL}'s electrician confirmed {D.he} had told {V} about the wiring twice the year before."),
        defendant: [.direct("What did you mean?", "\"That {V}'s wiring would burn that house down someday.\""),
               .direct("Why go over there?", "\"To tell {V.him} I knew what {V.he} said about me.\""),
               .direct("Why did you drive to {V}'s farm?", "\"I heard {V} had talked to the fire investigator about me. I wanted to tell {V.him} I knew what {V.he} said.\""),
               .direct("What did you say at the fence?", "\"That {V}'s old house had wiring that would burn it down someday, and I told {V.him} to think about that. I had warned {V.him} about it for years.\""),
               .direct("Had you warned {V} about the wiring before?", "\"Twice, the year before. My electrician was with me both times, and he can say so. {V} never listened.\""),
               .direct("Where did you go afterward?", "\"I drove home. I may have driven past {V}'s house later, and I did not stop or get out.\""),
               .cross("'Think about that tonight.'", "\"I was angry. I said it in the heat of the moment, and I didn't mean any harm.\""),
               .cross("You'd just been tried for burning a building.", "\"That's why I was angry.\""),
               .cross("You drove past three more times that night.", "\"I was driving around because I could not sleep. I did not go onto the property.\""),
               .cross("You knew {V} had talked to the fire investigator.", "\"I heard it from a neighbor. I was angry, and I should have gone home.\""),
                    .cross("{V}'s son recorded you saying it.", "\"He did. I heard the phone later, and I do not deny what is on it.\"")],
        openings: ("{D} drove to the farm of {V}, a neighbor who had talked to the fire investigator after a barn fire, and said across the fence, 'You know how fast an old house goes up. Think about that tonight.' {V}'s teenage son recorded the last part on his phone.", "The defense will say {D} was talking about {V}'s own bad wiring, which {D} had warned {V} about for years. A teenager overheard it in pieces, and {D} meant a warning, not a threat."),
        closings: ("Words about how fast an old house burns, said at a fence to a neighbor who had talked to the fire investigator, by a man tried over {PRIOR} for burning a building. {D} drove past {V}'s house three more times that night.", "{D} had warned {V} about the wiring twice before, as an electrician can confirm. A warning overheard in pieces is not a threat, and the State must prove {D} meant {V} to fear a fire."),
        timeline: [(0, "Evening: {DL} at {V}'s fence."), (1, "{V} reports it at dawn.")],
        identified: "The son's phone video.",
        impact: "\"I put cameras on every corner of the house after that day at the fence. I was told how fast an old house goes up, and I knew exactly what was meant. My wife won't stay there alone anymore, and we are thinking about selling the farm.\"")

    // MARK: - After the fire department money

    static let raffleMoney = followUp(
        key: "story.followup.raffleMoney", category: .whiteCollar,
        headlines: ["Church Raffle Money Missing; Former Fire Department Treasurer Charged", "Second Embezzlement Case for Former Treasurer"],
        law: "embezzlement", threshold: 6, spec: "Being entrusted as a volunteer with funds of a church raffle, fraudulently embezzled $4,800, on {DATE}.", ages: 35...68, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a church in {HOOD} let {D} volunteer to sell raffle tickets for a truck to benefit its food pantry. {DL} sold 480 tickets at $10 and turned in $1,200. The church's pastor found the ticket stubs: 480 names, phone numbers, and dates. A casino player's card shows {DL} buying in for $3,500 the weekend before the drawing.",
        state: [E(.document, 3, "Ticket Stubs", "480 stubs, each $10, in {DL}'s handwriting."),
                E(.document, 3, "Casino Records", "$3,500 in buy-ins on {DL}'s player's card the weekend before the drawing.")],
        defense: [E(.statement, 1, "Unpaid Tickets", "{DL} says many buyers promised to pay later and never did.")],
        witnessRole: "Pastor",
        exam: [.direct("What did you find?", "\"Four hundred eighty stubs. I called sixty buyers. Every one said they paid cash.\""),
               .direct("Did you know about {DL}'s earlier case?", "\"Yes. We believe in second chances. Maybe too much.\""),
               .direct("How did {DL} come to sell tickets for the church?", "\"{DL} asked to volunteer, and the board agreed. Tickets were $10 each, for a truck raffle to benefit our food pantry.\""),
               .direct("How much did {DL} turn in?", "\"$1,200. {DL} sold 480 tickets at $10, which comes to $4,800, and turned in a quarter of it.\""),
               .direct("What did you find in the ticket stubs?", "\"480 stubs in {DL}'s handwriting, each with a name, a phone number and the price of $10.\""),
               .direct("What did you learn about the money?", "\"I called sixty of the buyers, and every one said they paid cash. The casino's records show $3,500 in buy-ins on {DL}'s player's card the weekend before the drawing.\""),
               .cross("Some people do promise to pay later.", "\"Not one of the sixty I called.\""),
               .cross("You didn't call the other 420.", "\"No. I didn't call the other 420, and I never planned to.\""),
               .cross("The church had no controls on the money?", "\"That is true. The church secretary counted the money alone, and I have learned she kept some of it. That is a failure of ours.\""),
               .cross("A bank deposit slip for $3,400 turned up?", "\"A deposit slip for $3,400 in cash, dated the day after the ticket sales ended, was found in a later search. It was not turned over to the church.\""),
                    .cross("The casino records show nothing about the raffle money, do they?", "\"They show $3,500 in buy-ins on {DL}'s card the weekend before the drawing. Whether that was raffle cash I cannot say.\"")],
        theory: ("{D} sold $4,800 in raffle tickets, turned in $1,200, and went to the casino.", "Unpaid tickets and a church that never set up any controls."),
        allocution: "\"I sold maybe a third of those tickets on the promise that people would pay at the drawing. I go to the church sometimes, and some of them did. I'm in a treatment program now, and I'll pay the church back every dollar.\"",
        truths: ("{DL}'s bank deposit slip for $3,400 in cash, dated the day after ticket sales ended, turned up in a later search.",
                 "The church secretary, who counted the money alone, was found to have kept part of it."),
        defendant: [.direct("How many tickets were paid?", "\"Maybe a third. People said they'd pay at the drawing.\""),
               .direct("And the casino?", "\"I go sometimes. It's not a regular thing, just a night out now and then.\""),
               .direct("How did you sell the tickets?", "\"At church events and around town. I wrote each name and number on a stub and gave the buyer the other half.\""),
               .direct("What did you do with the cash you collected?", "\"Some went to the church and some stayed with me for a few days. I meant to deposit it after the drawing, and I did not.\""),
               .direct("Why did you go to the casino?", "\"I go sometimes. It is not a regular thing, just a night out now and then, and I used my own money.\""),
               .direct("What happened to the truck raffle?", "\"The drawing was never held. Several people asked about it, and I told them it was being rescheduled.\""),
                    .cross("Sixty buyers say they paid cash.", "\"Some of the sixty buyers did pay cash, but not all of them.\""),
               .cross("After your last case, you volunteered to handle cash again.", "\"They asked me, and I said yes. The board knew about my record and trusted me anyway, and I let them down.\""),
               .cross("You played with $3,500 the weekend before the drawing.", "\"That was my own money from my work, not the raffle. I know it looks bad.\""),
                    .cross("You turned in only $1,200 of $4,800.", "\"That is what I had collected in cash. The rest was people who said they would pay at the drawing.\""), .cross("You played at the casino with $3,500.", "\"That was money from my paychecks. I would not use the church's money, and I regret going.\"")],
        openings: ("A church let {D} volunteer to sell $10 raffle tickets for a truck to benefit its food pantry. {D} sold 480 tickets, worth $4,800, and turned in $1,200, and casino records show $3,500 in buy-ins on {D}'s player's card the weekend before the drawing.", "The defense will say many buyers promised to pay later and never did, and the church had no controls on the money. The church secretary counted it alone and was later found to have kept part of it."),
        closings: ("Four hundred eighty stubs in {D}'s handwriting, sixty buyers who say they paid cash, $1,200 turned in, and a casino weekend. {D} was asked to handle cash again after {PRIOR}.", "A church with no controls, a secretary who counted alone and kept some, and buyers who promised to pay later. The State must prove {D} kept the missing money."),
        timeline: [(-30, "Raffle sales begin."), (-3, "Casino buy-ins."), (0, "{DL} turns in $1,200 at the drawing.")],
        identified: "The ticket stubs and the casino records.",
        impact: nil)

    // MARK: - After the cattle sale

    static let trailerCattle = followUp(
        key: "story.followup.trailerCattle", category: .property,
        headlines: ["Stock Trailer Stolen From Sale Barn Lot", "Cattle Case Defendant Charged in Trailer Theft"],
        law: "felonyLarceny", lesser: "misdLarceny", threshold: 6, spec: "Stole a 20-foot livestock trailer valued at $9,500 belonging to {V}, on {DATE}.", ages: 28...62, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s 20-foot stock trailer disappeared from the Hollis Livestock Market's lot on a Tuesday night. A month later a deputy spotted it behind {D}'s barn with the VIN plate pried off and the fenders painted red. {DL} says {D.he} bought it for $2,000 cash from a man at a gas station.",
        state: [E(.physical, 3, "The Trailer", "The VIN plate pried off; the hidden frame VIN matches {V}'s trailer."),
                E(.document, 2, "Value", "A 2019 20-foot gooseneck stock trailer, valued at $9,500.")],
        defense: [E(.statement, 1, "Purchase", "{DL} says {D.he} paid $2,000 cash to a stranger and got no title.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("How did you identify the trailer?", "\"Manufacturers stamp a second VIN on the frame. It matched {V}'s.\""),
               .direct("What had been done to it?", "\"VIN plate pried off, fenders painted red over silver.\""),
               .direct("What was taken from the market lot?", "\"{V}'s 20-foot stock trailer, a 2019 gooseneck valued at $9,500, disappeared from the Hollis Livestock Market's lot on a Tuesday night.\""),
               .direct("Where did you find it?", "\"A month later, behind {DL}'s barn. The VIN plate was pried off and the fenders were painted red over the original silver.\""),
               .direct("What does the lot camera show?", "\"{DL}'s truck hitching the trailer at 11 p.m. on Tuesday. The picture is clear enough to read the truck.\""),
               .direct("What did {DL} tell you when you found the trailer?", "\"That {D.he} bought it from a man at a gas station and had no title. {D.He} said {D.he} painted it to fix the rust.\""),
                    .cross("{DL} says {D.he} bought it.", "\"No title, no bill of sale, no name for the seller.\""),
               .cross("Painting fenders isn't a crime.", "\"Prying off a VIN plate is a sign.\""),
               .cross("A man in Virginia named {DL} as a buyer?", "\"A man arrested in Virginia for a string of trailer thefts named {DL} as one of his buyers. I do not know whether he named {DL} as the man at the lot.\""),
                    .cross("The VIN plate could have been pried off by the seller?", "\"It could have. That is the explanation {DL} gives, and I have no way to disprove it.\""), .cross("{DL} did not try to hide the trailer?", "\"It was behind {D.his} barn, in plain view of the road. {D.He} did not hide it, and I noted that.\"")],
        theory: ("{D} took {V}'s trailer from the sale barn lot, pried off the VIN, and painted it.", "{D} bought a trailer too cheap from a stranger. That's foolish, not theft."),
        allocution: "\"A man at a gas station on Route 17 sold me that trailer for two thousand dollars. It was already like that when I got it, with the plate missing. I thought it was a deal. I should have known better than to buy without a title, and I'm sorry to {V}.\"",
        truths: ("The sale barn's lot camera showed {DL}'s truck hitching the trailer at 11 p.m.",
                 "A man arrested in Virginia for a string of trailer thefts named {DL} as one of his buyers."),
        defendant: [.direct("Where did you get the trailer?", "\"A man at a gas station on Route 17 sold it for two thousand cash.\""),
               .direct("Who pried off the plate?", "\"It was like that when I got it.\""),
               .direct("Why did you buy it?", "\"I needed a trailer for my cattle, and I thought it was a good deal. I did not look hard at the paperwork.\""),
               .direct("Why did you paint the fenders?", "\"They were rusty. I painted them because they had rust spots, and it looked bad.\""),
               .direct("Where were you the night the trailer was taken?", "\"At home. My truck was in the yard, and my family was there. I did not go near the sale barn.\""),
               .direct("What did you plan to do with the trailer?", "\"Haul cattle to the sale barn for myself and a few neighbors. I needed one and I could not afford a new one.\""),
               .cross("A $9,500 trailer for $2,000 cash and no title.", "\"I thought it was a deal.\""),
               .cross("You painted the fenders.", "\"They were rusty. I painted the fenders because they had rust spots.\""),
               .cross("Your truck is on the lot camera at 11 p.m.", "\"I do not know how. I was at home that night. A lot of trucks look like mine.\""),
               .cross("Even a Virginia man says you bought from him.", "\"I do not know that man. I never bought from anyone in Virginia.\""),
                    .cross("You bought a trailer worth $9,500 for $2,000.", "\"It was a good price, and I took it. I know now what a price like that can mean.\"")],
        openings: ("{V}'s 20-foot stock trailer disappeared from the livestock market lot on a Tuesday night, and a month later a deputy spotted it behind {D}'s barn with the VIN plate pried off and the fenders painted red. The frame VIN matches {V}'s trailer.", "The defense will say {D} paid $2,000 in cash to a stranger at a gas station and painted rusty fenders, which was foolish but not theft. {D} did not take the trailer from the lot."),
        closings: ("The pried-off plate, the red paint over silver, the hidden frame VIN, and a lot camera showing {D}'s truck hitching the trailer at 11 p.m. {D} was back after {PRIOR}.", "A bargain with no title is careless, and a lot camera at night shows a truck that looks like {D}'s. The State must prove {D} took the trailer or knew it was stolen."),
        timeline: [(0, "Tuesday night: trailer taken from the sale barn lot."), (30, "Deputy finds it behind {DL}'s barn.")],
        identified: "The hidden frame VIN.",
        impact: "\"That trailer is how I haul my calves to market, and it was gone from the lot overnight. I rented one for six weeks while I waited, which cost me money I didn't have. When it came back the VIN plate had been taken off, and I'll always wonder what else was done to it.\"")

    // MARK: - After the flashlight

    static let bouncerSecondFight = followUp(
        key: "story.followup.bouncerSecondFight", category: .violent,
        headlines: ["Former Bouncer Charged in Second Alley Fight", "Patron's Jaw Broken Outside Bar; Security Guard Charged"],
        law: "aisi", threshold: 5, spec: "Assaulted {V}, inflicting serious injury, a broken jaw, on {DATE}.", ages: 23...47, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} took a security job at another bar. On {DATE}, {DL} punched {V}, a customer who'd been thrown out, after {V} came back to the door yelling. {V}'s jaw broke in two places. A door camera shows {V} with {V.his} hands in {V.his} pockets when {DL} swung.",
        state: [E(.video, 3, "Door Camera", "{V} stands yelling with hands in pockets; {D} steps out and punches."),
                E(.document, 2, "Medical Records", "Jaw fractured in two places; wired shut six weeks.")],
        defense: [E(.statement, 1, "Threat", "{DL} says {V} said \"I've got something for you\" and reached in a pocket.")],
        witnessRole: "Police officer",
        exam: [.direct("What does the camera show?", "\"{V} yelling, hands in pockets the whole time. {DL} steps out and hits {V.him}.\""),
               .direct("Did {V} have anything?", "\"A phone and a lighter.\""),
               .direct("What did you find when you arrived at the bar?", "\"{V} on the ground outside the door with a broken jaw, and {DL} standing nearby. A crowd had gathered, and a door camera had recorded it.\""),
               .direct("How serious was the injury?", "\"{V}'s jaw was fractured in two places. {V.he} was wired shut for six weeks and lost a lot of weight.\""),
               .direct("What did {V} have on {V.him}?", "\"A phone and a lighter. No weapon was found on {V}.\""),
               .direct("What did the bar's security staff tell you?", "\"That {V} had been put out earlier for being drunk and had come back to the door yelling. They said {DL} stepped out to handle it.\""),
                    .cross("Hands in pockets can hide a weapon.", "\"They can. I couldn't see them, so I couldn't rule it out.\""),
               .cross("{V} came back after being thrown out.", "\"Yelling isn't a reason to break a jaw.\""),
               .cross("{V}'s hands were in {V.his} pockets, weren't they?", "\"The whole time. A hand in a pocket can hide a weapon, and I could not see them, so I cannot rule it out.\""),
               .cross("{V} said something threatening?", "\"{DL} says {V} said, 'I've got something for you,' and reached in a pocket. The camera has no sound.\""),
               .cross("A coworker heard {DL} say something before going out?", "\"A coworker said {DL} told him, 'I'm not waiting to see what comes out of a pocket again.' It was a reference to the earlier case.\"")],
        theory: ("{D} broke a yelling man's jaw while {V.his} hands were in {V.his} pockets.", "Another threat, another reach, and a guard who'd learned what a pocket can hold."),
        allocution: "\"{V.He} said {V.he} had something for me and went into {V.his} pocket, and I didn't wait. After the last time in this court, every pocket looks like a knife to me. I couldn't know what {V} had.\"",
        truths: ("A coworker said {DL} told him, \"I'm not waiting to see what comes out of a pocket again,\" before stepping outside.",
                 "{V} admitted at a later civil deposition that {V.he} had a box cutter in that pocket and meant to use it."),
        defendant: [.direct("Why did you swing?", "\"{V.He} said '{V.he} had something for me' and went in {V.his} pocket.\""),
               .direct("Did you see a weapon?", "\"I didn't wait to. I saw the hands in the pockets and reacted before I could see anything.\""),
               .direct("How did the night go?", "\"{V} had been thrown out for being drunk and started yelling at the door. He came back and kept shouting at the customers.\""),
               .direct("What did {V} say to you?", "\"That {V.he} had something for me. {V.He} put a hand in {V.his} pocket, and I did not see what was in it.\""),
               .direct("What did you do?", "\"I stepped out and hit him once. I did not wait to see a weapon, because the last time I waited, someone was hurt.\""),
               .direct("Did you know how badly {V} was hurt?", "\"Not until the ambulance came. I called for help and stayed with {V.him}, and I was shocked.\""),
               .cross("{V}'s hands never came out of the pockets.", "\"I couldn't see {V.his} hands, so I didn't know what was in them.\""),
               .cross("Your last case was the same thing.", "\"That's why I'm careful. Because my last case was the same thing, I tried to be more careful this time.\""),
               .cross("Yelling is not a reason to break a jaw.", "\"It is not. I did not mean to break it. I punched once, and I did not think it would do that.\""),
                    .cross("You hit a man who was standing with his hands in his pockets.", "\"I did, and I have thought about that every day. I was afraid, and I did not wait to see what was in them.\""), .cross("{V} had a phone and a lighter.", "\"I did not know that. I found out after the ambulance came, and I would give a lot to undo it.\"")],
        openings: ("{D} took a security job at another bar, and when {V}, a customer who had been thrown out, came back to the door yelling, {D} stepped out and punched {V}. {V}'s jaw was broken in two places, and the door camera shows {V}'s hands in {V.his} pockets.", "The defense will say {V} said, 'I've got something for you,' and reached into a pocket, and that {D}, a guard burned once before, reacted before a weapon could come out. {V} later admitted a box cutter was in that pocket."),
        closings: ("A yelling man with his hands in his pockets was punched hard enough to break his jaw in two places, wired shut for six weeks. {D} was back after {PRIOR}, and no weapon was found.", "{D} had been burned by a reach into a pocket before, and {V} later admitted a box cutter was there. The State must prove {D} was not in fear when {D.he} swung."),
        timeline: [(0, "12:40 a.m.: {V} thrown out; 12:55 a.m.: returns; punch.")],
        identified: "The door camera.",
        impact: "\"I ate through a straw for six weeks. I'd been drinking at a bar, and I said something stupid, and a bouncer broke my jaw. I lost twenty pounds. I couldn't work, and my boss said not to come back until I could talk.\"",
        doctrines: ["selfDefense", "burdenOfProof"])
}
